item.stdout:
# Direct event submissions

`POST /api/v1/submissions` accepts JSON from an authenticated, approved submitter. The backend
looks up the fixture's competition and compares it with the account's server-owned competition
scope. Client-supplied roles or scope values are ignored.

The current schema version is `1.0`. A request contains one fixture and 1â€“1,000 ordered cricket
delivery events. Events for each innings must appear in ascending `sequenceNumber` order. Statistics
are not accepted: the platform derives them from accepted deliveries.

```http
POST /api/v1/submissions
Authorization: Bearer <supabase-access-token>
Content-Type: application/json
```

```json
{
  "fixtureId": "42",
  "schemaVersion": "1.0",
  "events": [
    {
      "eventId": "123e4567-e89b-42d3-a456-426614174000",
      "inningsId": "81",
      "sequenceNumber": 1,
      "overNumber": 0,
      "positionInOver": 0,
      "ballNumber": "0.1",
      "strikerId": "101",
      "nonStrikerId": "102",
      "bowlerId": "201",
      "runs": {
        "offBat": 4,
        "extras": 0,
        "total": 4,
        "nonBoundary": false
      },
      "extras": {},
      "wickets": []
    }
  ]
}
```

Successful validation and storage are synchronous and atomic:

```http
HTTP/1.1 201 Created
```

```json
{
  "data": {
    "submissionId": "300",
    "fixtureId": "42",
    "submitterId": "17",
    "status": "accepted",
    "receivedAt": "2026-08-13T16:00:00.000Z",
    "schemaVersion": "1.0",
    "eventCount": 1
  }
}
```

The backend records the submitter, fixture, received timestamp, schema version, original event ID,
and zero-based event-array position. A globally unique event UUID protects against accidental retry
or replay. If any event is invalid or conflicts, the transaction rolls back and stores neither the
submission nor any of its events.

Responses are `401` for missing or invalid authentication, `403` for unapproved or out-of-scope
accounts, `409` for event conflicts, `413` above the 1 MB JSON limit, `422` for contract or reference
validation, and `429` after 30 requests from one account in 60 seconds. Validation details include a
field path and `eventIndex` where applicable.

## AI Declaration

The direct submission API documentation was generated with the assistance of Codex[GPT-5.6 Sol].

import { z } from 'zod';

import { apiDateTimeSchema, apiIdentifierSchema } from './api';

export const DIRECT_SUBMISSION_SCHEMA_VERSION = '1.0' as const;

const databaseIdentifierSchema = apiIdentifierSchema
  .regex(/^[1-9]\d*$/, 'Expected a positive database identifier.')
  .max(19)
  // Zod runs every check on a string rather than stopping at the first failure,
  // so this refinement sees values the regex has already rejected. BigInt throws
  // on those, which escapes safeParse and surfaces as an unexplained server
  // error rather than a validation failure.
  .refine(
    (value) => {
      if (!/^\d+$/.test(value)) {
        return true;
      }

      return BigInt(value) <= 9_223_372_036_854_775_807n;
    },
    {
      message: 'Database identifier is outside the supported range.',
    },
  );

const smallNonNegativeIntegerSchema = z.number().int().min(0).max(32_767);

export const submissionEventIdSchema = z
  .string()
  .uuid('Event identifiers must be UUIDs so retries and accidental duplicates can be detected.');

export const submissionWicketSchema = z
  .object({
    // The dismissal vocabulary is held in the dismissal_kind lookup table rather
    // than enumerated here. The set is open: two kinds present in the full corpus
    // were absent from the earlier subset, and the migration records that
    // extending an enumeration would require a migration. The contract therefore
    // constrains the shape and the service resolves the value against the table,
    // so a new kind needs a row and no code change.
    kind: z
      .string()
      .min(1)
      .max(64)
      .regex(/^[a-z][a-z ]*$/, 'A dismissal kind is lower-case words separated by spaces.'),
    playerOutId: databaseIdentifierSchema,
    fielders: z
      .array(
        z
          .object({
            participantId: databaseIdentifierSchema.optional(),
            substitute: z.boolean().default(false),
          })
          .strict()
          .refine((fielder) => fielder.participantId !== undefined || fielder.substitute, {
            message: 'A fielder must identify a participant or be marked as a substitute.',
          }),
      )
      .max(11)
      .default([]),
  })
  .strict();

export const submissionEventSchema = z
  .object({
    eventId: submissionEventIdSchema,
    inningsId: databaseIdentifierSchema,
    sequenceNumber: z.number().int().positive().max(2_147_483_647),
    overNumber: smallNonNegativeIntegerSchema,
    positionInOver: smallNonNegativeIntegerSchema,
    // The printed ball number is display only: it is never unique and never used
    // to join, because it counts legal deliveries and so repeats within an over.
    // The identifying columns are overNumber and positionInOver. Constrained to
    // the printed form so that a submitted label cannot be arbitrary text, but
    // the platform does not currently verify that it agrees with the position it
    // describes.
    ballNumber: z
      .string()
      .regex(
        /^\d{1,3}\.\d{1,2}$/,
        'A printed ball number takes the form <over>.<ball>, for example 5.1.',
      ),
    strikerId: databaseIdentifierSchema,
    nonStrikerId: databaseIdentifierSchema,
    bowlerId: databaseIdentifierSchema,
    runs: z
      .object({
        offBat: smallNonNegativeIntegerSchema,
        extras: smallNonNegativeIntegerSchema,
        total: smallNonNegativeIntegerSchema,
        nonBoundary: z.boolean().default(false),
      })
      .strict(),
    extras: z
      .object({
        wides: smallNonNegativeIntegerSchema.optional(),
        noBalls: smallNonNegativeIntegerSchema.optional(),
        byes: smallNonNegativeIntegerSchema.optional(),
        legByes: smallNonNegativeIntegerSchema.optional(),
        penalty: smallNonNegativeIntegerSchema.optional(),
      })
      .strict()
      .default({}),
    wickets: z.array(submissionWicketSchema).max(2).default([]),
  })
  .strict()
  .superRefine((event, context) => {
    if (event.strikerId === event.nonStrikerId) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['nonStrikerId'],
        message: 'The striker and non-striker must be different participants.',
      });
    }

    if (event.runs.total !== event.runs.offBat + event.runs.extras) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['runs', 'total'],
        message: 'Total runs must equal off-bat runs plus extras.',
      });
    }

    const extrasTotal = Object.values(event.extras).reduce<number>(
      (total, value) => total + (value ?? 0),
      0,
    );

    if (event.runs.extras !== extrasTotal) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['runs', 'extras'],
        message: 'Run extras must equal the supplied extras breakdown.',
      });
    }
  });

export const submissionRequestSchema = z
  .object({
    fixtureId: databaseIdentifierSchema,
    schemaVersion: z.literal(DIRECT_SUBMISSION_SCHEMA_VERSION),
    events: z.array(submissionEventSchema).min(1).max(1_000),
  })
  .strict()
  .superRefine((submission, context) => {
    const eventIds = new Set<string>();
    const sequenceKeys = new Set<string>();
    const positions = new Set<string>();
    const lastSequenceByInnings = new Map<string, number>();

    for (const [eventIndex, event] of submission.events.entries()) {
      if (eventIds.has(event.eventId)) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['events', eventIndex, 'eventId'],
          message: 'Event identifiers must be unique within a submission.',
        });
      }
      eventIds.add(event.eventId);

      const sequenceKey = `${event.inningsId}:${event.sequenceNumber}`;
      if (sequenceKeys.has(sequenceKey)) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['events', eventIndex, 'sequenceNumber'],
          message: 'Sequence numbers must be unique within an innings.',
        });
      }
      sequenceKeys.add(sequenceKey);

      const previousSequence = lastSequenceByInnings.get(event.inningsId);
      if (previousSequence !== undefined && event.sequenceNumber <= previousSequence) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['events', eventIndex, 'sequenceNumber'],
          message: 'Events for each innings must appear in ascending sequence order.',
        });
      }
      lastSequenceByInnings.set(event.inningsId, event.sequenceNumber);

      const positionKey = `${event.inningsId}:${event.overNumber}:${event.positionInOver}`;
      if (positions.has(positionKey)) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['events', eventIndex, 'positionInOver'],
          message: 'Delivery positions must be unique within an innings.',
        });
      }
      positions.add(positionKey);
    }
  });

export const submissionSchema = z.object({
  submissionId: apiIdentifierSchema,
  fixtureId: apiIdentifierSchema,
  submitterId: apiIdentifierSchema,
  status: z.literal('accepted'),
  receivedAt: apiDateTimeSchema,
  schemaVersion: z.literal(DIRECT_SUBMISSION_SCHEMA_VERSION),
  eventCount: z.number().int().positive(),
});

export const submissionResponseSchema = z.object({
  data: submissionSchema,
});

export type SubmissionRequest = z.infer<typeof submissionRequestSchema>;
export type SubmissionEvent = z.infer<typeof submissionEventSchema>;
export type SubmissionResponse = z.infer<typeof submissionResponseSchema>;

import request from 'supertest';
import { describe, expect, test, vi } from 'vitest';

import type { VerifyAccessToken } from '../../src/auth/supabase-auth';
import type { SynchronizeAccount } from '../../src/modules/accounts/account.service';
import type { SubmissionRepository } from '../../src/modules/submissions/submission.repository';
import {
  createSubmissionService,
  type SubmissionService,
} from '../../src/modules/submissions/submission.service';
import { createTestAccount, createTestApp } from '../test-app';

const validPayload = {
  fixtureId: '7',
  schemaVersion: '1.0' as const,
  events: [
    {
      eventId: '123e4567-e89b-42d3-a456-426614174000',
      inningsId: '10',
      sequenceNumber: 1,
      overNumber: 0,
      positionInOver: 0,
      ballNumber: '0.1',
      strikerId: '20',
      nonStrikerId: '21',
      bowlerId: '22',
      runs: {
        offBat: 4,
        extras: 0,
        total: 4,
      },
    },
  ],
};

const acceptToken: VerifyAccessToken = async () => ({
  uid: 'approved-user',
  displayName: 'Approved User',
});

function synchronizeWith(account: ReturnType<typeof createTestAccount>): SynchronizeAccount {
  return async () => account;
}

function mockSubmissionService(): SubmissionService {
  return {
    submit: vi.fn<SubmissionService['submit']>().mockResolvedValue({
      data: {
        submissionId: '30',
        fixtureId: '7',
        submitterId: '1',
        status: 'accepted',
        receivedAt: '2026-08-13T16:00:00.000Z',
        schemaVersion: '1.0',
        eventCount: 1,
      },
    }),
  };
}

describe('direct event submission API', () => {
  test('rejects anonymous requests before submission processing', async () => {
    const verifyAccessToken = vi.fn<VerifyAccessToken>();
    const service = mockSubmissionService();

    const response = await request(
      createTestApp(verifyAccessToken, undefined, undefined, undefined, service),
    )
      .post('/api/v1/submissions')
      .send(validPayload)
      .expect('WWW-Authenticate', 'Bearer')
      .expect(401);

    expect(response.body.error.code).toBe('UNAUTHORIZED');
    expect(service.submit).not.toHaveBeenCalled();
  });

  test('rejects signed-in users who are not approved submitters', async () => {
    const service = mockSubmissionService();

    const response = await request(
      createTestApp(
        acceptToken,
        undefined,
        synchronizeWith(createTestAccount({ approvalState: 'pending' })),
        undefined,
        service,
      ),
    )
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer pending-token')
      .send(validPayload)
      .expect(403);

    expect(response.body.error.code).toBe('FORBIDDEN');
    expect(service.submit).not.toHaveBeenCalled();
  });

  test('accepts and reports provenance for an approved in-scope submitter', async () => {
    const service = mockSubmissionService();
    const account = createTestAccount({
      approvalState: 'approved',
      competitionIds: ['5'],
    });

    const response = await request(
      createTestApp(acceptToken, undefined, synchronizeWith(account), undefined, service),
    )
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer approved-token')
      .send(validPayload)
      .expect(201);

    expect(service.submit).toHaveBeenCalledWith(
      account,
      expect.objectContaining({
        fixtureId: '7',
        schemaVersion: '1.0',
      }),
    );
    expect(response.body).toEqual({
      data: {
        submissionId: '30',
        fixtureId: '7',
        submitterId: '1',
        status: 'accepted',
        receivedAt: '2026-08-13T16:00:00.000Z',
        schemaVersion: '1.0',
        eventCount: 1,
      },
    });
  });

  test('rejects an approved submitter outside the fixture competition scope', async () => {
    const storeAcceptedSubmission = vi.fn<SubmissionRepository['storeAcceptedSubmission']>();
    const repository: SubmissionRepository = {
      async findFixtureScope() {
        return { fixtureId: '7', competitionId: '5' };
      },
      storeAcceptedSubmission,
    };
    const service = createSubmissionService(repository);

    const response = await request(
      createTestApp(
        acceptToken,
        undefined,
        synchronizeWith(createTestAccount({ approvalState: 'approved', competitionIds: ['6'] })),
        undefined,
        service,
      ),
    )
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer out-of-scope-token')
      .send(validPayload)
      .expect(403);

    expect(response.body.error.code).toBe('FORBIDDEN');
    expect(storeAcceptedSubmission).not.toHaveBeenCalled();
  });

  test('returns event-indexed validation details without invoking storage', async () => {
    const service = mockSubmissionService();

    const response = await request(
      createTestApp(
        acceptToken,
        undefined,
        synchronizeWith(createTestAccount({ approvalState: 'approved' })),
        undefined,
        service,
      ),
    )
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer approved-token')
      .send({
        ...validPayload,
        events: [
          {
            ...validPayload.events[0],
            runs: { offBat: 4, extras: 1, total: 4 },
          },
        ],
      })
      .expect(422);

    expect(response.body.error.code).toBe('VALIDATION_FAILED');
    expect(response.body.error.details).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          field: 'events.0.runs.total',
          eventIndex: 0,
        }),
      ]),
    );
    expect(service.submit).not.toHaveBeenCalled();
  });

  test('enforces the authenticated submission rate limit', async () => {
    const service = mockSubmissionService();
    const app = createTestApp(
      acceptToken,
      undefined,
      synchronizeWith(createTestAccount({ approvalState: 'approved' })),
      undefined,
      service,
    );

    for (let requestNumber = 0; requestNumber < 30; requestNumber += 1) {
      await request(app)
        .post('/api/v1/submissions')
        .set('Authorization', 'Bearer approved-token')
        .send(validPayload)
        .expect(201);
    }

    const response = await request(app)
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer approved-token')
      .send(validPayload)
      .expect(429);

    expect(response.body.error.code).toBe('RATE_LIMIT_EXCEEDED');
    expect(Number(response.headers['retry-after'])).toBeGreaterThan(0);
    expect(service.submit).toHaveBeenCalledTimes(30);
  });

  test('returns predictable errors for malformed JSON and oversized payloads', async () => {
    const service = mockSubmissionService();
    const app = createTestApp(
      acceptToken,
      undefined,
      synchronizeWith(createTestAccount({ approvalState: 'approved' })),
      undefined,
      service,
    );

    const malformed = await request(app)
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer approved-token')
      .set('Content-Type', 'application/json')
      .send('{')
      .expect(400);
    expect(malformed.body.error.code).toBe('INVALID_JSON');

    const oversized = await request(app)
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer approved-token')
      .send({ ignored: 'x'.repeat(1_050_000) })
      .expect(413);
    expect(oversized.body.error.code).toBe('PAYLOAD_TOO_LARGE');
  });
  test('rejects an unrecognised dismissal kind with the field and value that caused it', async () => {
    const storeAcceptedSubmission = vi.fn<SubmissionRepository['storeAcceptedSubmission']>();
    const repository: SubmissionRepository = {
      async findFixtureScope() {
        return { fixtureId: '7', competitionId: '5' };
      },
      async findDismissalKinds() {
        return new Set(['caught', 'bowled', 'run out']);
      },
      storeAcceptedSubmission,
    };
    const service = createSubmissionService(repository);

    const response = await request(
      createTestApp(
        acceptToken,
        undefined,
        synchronizeWith(createTestAccount({ approvalState: 'approved', competitionIds: ['5'] })),
        undefined,
        service,
      ),
    )
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer approved-token')
      .send({
        ...validPayload,
        events: [
          {
            ...validPayload.events[0],
            wickets: [
              {
                kind: 'dismissed by vibes',
                playerOutId: '20',
              },
            ],
          },
        ],
      })
      .expect(422);

    expect(response.body.error.details).toHaveLength(1);
    expect(response.body.error.details[0]).toMatchObject({
      code: 'UNKNOWN_DISMISSAL_KIND',
      field: 'wickets.kind',
      eventIndex: 0,
    });
    expect(response.body.error.details[0].message).toContain('dismissed by vibes');
    expect(storeAcceptedSubmission).not.toHaveBeenCalled();
  });

  test('accepts a dismissal kind held in the lookup table without a contract change', async () => {
    const repository: SubmissionRepository = {
      async findFixtureScope() {
        return { fixtureId: '7', competitionId: '5' };
      },
      // A kind absent from any enumeration in the contract. The vocabulary is
      // held in dismissal_kind precisely so that adding one needs a row, not a
      // code change.
      async findDismissalKinds() {
        return new Set(['caught', 'bowled', 'retired not out']);
      },
      async storeAcceptedSubmission() {
        return {
          submissionId: '30',
          fixtureId: '7',
          submitterId: '1',
          status: 'accepted' as const,
          receivedAt: '2026-08-13T16:00:00.000Z',
          schemaVersion: '1.0' as const,
          eventCount: 1,
        };
      },
    };
    const service = createSubmissionService(repository);

    await request(
      createTestApp(
        acceptToken,
        undefined,
        synchronizeWith(createTestAccount({ approvalState: 'approved', competitionIds: ['5'] })),
        undefined,
        service,
      ),
    )
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer approved-token')
      .send({
        ...validPayload,
        events: [
          {
            ...validPayload.events[0],
            wickets: [{ kind: 'retired not out', playerOutId: '20' }],
          },
        ],
      })
      .expect(201);
  });

  test('rejects a printed ball number that is not in the published form', async () => {
    const service = mockSubmissionService();

    const response = await request(
      createTestApp(
        acceptToken,
        undefined,
        synchronizeWith(createTestAccount({ approvalState: 'approved' })),
        undefined,
        service,
      ),
    )
      .post('/api/v1/submissions')
      .set('Authorization', 'Bearer approved-token')
      .send({
        ...validPayload,
        events: [{ ...validPayload.events[0], ballNumber: 'first ball of the over' }],
      })
      .expect(422);

    expect(response.body.error.details[0]).toMatchObject({
      field: 'events.0.ballNumber',
      eventIndex: 0,
    });
    expect(service.submit).not.toHaveBeenCalled();
  });
});

