    expect(response.body).toEqual({
      data: {
        submissionId: '30',
        fixtureId: '7',
        submitterId: '1',
        status: 'accepted',
        receivedAt: '2026-08-13T16:00:00.000Z',
        schemaVersion: '1.0',
        eventCount: 1,
      },
    });
