import { submissionRequestSchema } from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import { rejectAuthorization } from '../../middleware/authorization-response';
import type { ApplicationAccount } from '../accounts/account';
import {
  SubmissionConflictError,
  SubmissionForbiddenError,
  SubmissionValidationError,
} from './submission.errors';
import type { SubmissionService } from './submission.service';

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Submission controller requires an authenticated application account');
  }

  return account;
}

export function createSubmissionController(service: SubmissionService): RequestHandler {
  return (request, response, next) => {
    const parsed = submissionRequestSchema.safeParse(request.body);

    if (!parsed.success) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submission is invalid.',
          details: parsed.error.issues.map((issue) => {
            const eventPathIndex = issue.path[0] === 'events' ? issue.path[1] : undefined;
            return {
              code: 'INVALID_FIELD',
              message: issue.message,
              ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
              ...(typeof eventPathIndex === 'number' ? { eventIndex: eventPathIndex } : {}),
            };
          }),
        },
      });
      return;
    }

    let account: ApplicationAccount;
    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .submit(account, parsed.data)
      .then((submission) => {
        response.status(201).json(submission);
      })
      .catch((error: unknown) => {
        if (error instanceof SubmissionForbiddenError) {
          rejectAuthorization(response);
          return;
        }

        if (error instanceof SubmissionValidationError) {
          response.status(422).json({
            error: {
              code: 'VALIDATION_FAILED',
              message: error.message,
              details: error.details,
            },
          });
          return;
        }

        if (error instanceof SubmissionConflictError) {
          response.status(409).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        next(error);
      });
  };
}

import type { ApiErrorDetail } from '@sport-analytics/contracts';

export class SubmissionValidationError extends Error {
  constructor(
    message: string,
    public readonly details: ApiErrorDetail[],
  ) {
    super(message);
    this.name = 'SubmissionValidationError';
  }
}

export class SubmissionForbiddenError extends Error {
  constructor() {
    super('The authenticated account is not permitted to submit events for this fixture.');
    this.name = 'SubmissionForbiddenError';
  }
}

export class SubmissionConflictError extends Error {
  constructor(
    public readonly code: 'DUPLICATE_EVENT_ID' | 'EVENT_CONFLICT',
    message: string,
  ) {
    super(message);
    this.name = 'SubmissionConflictError';
  }
}

import { Router } from 'express';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireApprovedSubmitter } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import { createSubmissionController } from './submission.controller';
import { createSubmissionRateLimit } from './submission-rate-limit';
import type { SubmissionService } from './submission.service';

export function createSubmissionRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: SubmissionService,
): Router {
  const router = Router();

  router.post(
    '/submissions',
    requireAuthentication(verifyAccessToken, synchronizeAccount),
    requireApprovedSubmitter(),
    createSubmissionRateLimit(),
    createSubmissionController(service),
  );

  return router;
}

export interface HealthResponse {
  status: 'ok';
  service: string;
  timestamp: string;
}

const apiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? 'http://localhost:3000/api/v1';

export type ApiErrorKind = 'unauthenticated' | 'forbidden' | 'request-failed';

export class ApiResponseError extends Error {
  readonly kind: ApiErrorKind;
  readonly status: number;

  constructor(status: number, message = `API request failed with status ${status}`) {
    const kind =
      status === 401 ? 'unauthenticated' : status === 403 ? 'forbidden' : 'request-failed';

    super(message);
    this.name = 'ApiResponseError';
    this.kind = kind;
    this.status = status;
  }
}

export type AccessTokenProvider = () => string | null;

export interface AuthenticatedApiClient {
  request<ResponseBody>(path: string, init?: RequestInit): Promise<ResponseBody>;
}

export function createAuthenticatedApiClient(
  getAccessToken: AccessTokenProvider,
): AuthenticatedApiClient {
  return {
    async request<ResponseBody>(path: string, init: RequestInit = {}): Promise<ResponseBody> {
      const headers = new Headers(init.headers);
      const accessToken = getAccessToken();

      if (!headers.has('Accept')) {
        headers.set('Accept', 'application/json');
      }

      if (accessToken) {
        headers.set('Authorization', `Bearer ${accessToken}`);
      } else {
        headers.delete('Authorization');
      }

      const normalizedPath = path.startsWith('/') ? path : `/${path}`;
      const response = await fetch(`${apiBaseUrl}${normalizedPath}`, {
        ...init,
        headers,
      });

      if (!response.ok) {
        throw new ApiResponseError(response.status);
      }

      if (response.status === 204) {
        return undefined as ResponseBody;
      }

      return (await response.json()) as ResponseBody;
    },
  };
}

export async function getHealth(signal?: AbortSignal): Promise<HealthResponse> {
  const response = await fetch(`${apiBaseUrl}/health`, {
    headers: {
      Accept: 'application/json',
    },
    signal: signal ?? null,
  });

  if (!response.ok) {
    throw new Error(`Health request failed with status ${response.status}`);
  }

  return (await response.json()) as HealthResponse;
}

