      label="Competition"
      load={load}
      render={({ data: competition }) => {
        const id = encodeURIComponent(competition.competitionId);
        return (
          <DetailLayout
            backLabel="competitions"
            backTo="/competitions"
            eyebrow="Competition"
            title={competition.name}
          >
            <RecordFacts>
              <RecordFact label="Competition ID" value={competition.competitionId} />
