  --colour-text-secondary: #52636a;
  --colour-text-muted: #627078;
  --colour-border: #d9d3c4;
  --colour-primary: #5d7e00;
  --colour-primary-soft: #dff0a7;
  --colour-brand: #e95a24;
  --colour-data-accent: #007f9e;
  --colour-link: #005f77;
  --colour-label: #486200;
  --colour-brand-text: #a83b13;
  --colour-error: #b42318;
  --colour-focus: #007f9e;
  --colour-error: #d64251;
  --colour-error-soft: #fce8e8;
  --shadow-header: 0 8px 28px rgb(16 32 38 / 8%);
  --font-display: 'Arial Narrow', 'Roboto Condensed', Arial, sans-serif;
  --font-interface: 'Segoe UI', Arial, sans-serif;
  color: var(--colour-text);
  background: var(--colour-canvas);
  font-family: var(--font-interface);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

:root[data-theme='night'] {
  --colour-canvas: #08121b;
  --colour-surface: #101e2b;
  --colour-surface-raised: #162736;
  --colour-text: #f6f8f2;
  --colour-text-secondary: #b8c3cc;
  --colour-text-muted: #8ea0af;
  --colour-border: #263847;
  --colour-primary: #c7ff4a;
  --colour-primary-soft: #263b21;
  --colour-brand: #ff6b35;
  --colour-data-accent: #20d5ff;
  --colour-link: #20d5ff;
  --colour-label: #c7ff4a;
  --colour-brand-text: #ff8a5e;
  --colour-error: #ff8a7a;
  --colour-focus: #c7ff4a;
  --colour-error: #ff5a67;
  --colour-error-soft: #361b24;
  --shadow-header: 0 8px 28px rgb(0 0 0 / 24%);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  background: var(--colour-canvas);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--colour-canvas);
  color: var(--colour-text);
}

button,
input,
select {
  font: inherit;
}

a {
  color: var(--colour-link);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.public-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.skip-link {
  position: fixed;
  left: 1rem;
  top: -5rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  border: 2px solid var(--colour-focus);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 1rem;
}

.site-header {
  position: relative;
  z-index: 10;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.site-header__inner,
.site-footer__inner,
.content-boundary {
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
}

.site-header__inner {
  min-height: 5.5rem;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 1.5rem;
}

.site-header__controls,
.auth-navigation,
.auth-navigation-wrap {
  display: flex;
  align-items: center;
}

.site-header__controls {
  justify-content: flex-end;
  gap: 1.5rem;
}

.auth-navigation-wrap {
  position: relative;
  align-self: stretch;
}

.auth-navigation {
  gap: 0.5rem;
}

.auth-navigation a,
.auth-navigation button {
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
  padding: 0.625rem 0.75rem;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
}

.auth-navigation a:hover,
.auth-navigation button:hover:not(:disabled),
.auth-navigation a[aria-current='page'] {
  border-color: var(--colour-border);
  background: var(--colour-surface-raised);
}

.auth-navigation a[aria-current='page'] {
  box-shadow: inset 0 -3px var(--colour-primary);
}

.auth-navigation button:disabled {
  cursor: wait;
  opacity: 0.7;
}

.auth-navigation__status {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.auth-navigation__error {
  position: absolute;
  top: calc(100% - 0.25rem);
  right: 0;
  width: max-content;
  max-width: min(22rem, calc(100vw - 2rem));
  margin: 0;
  padding: 0.75rem 1rem;
  border: 1px solid var(--colour-error);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-error);
  box-shadow: var(--shadow-header);
  font-size: 0.875rem;
}

.brand-link {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  border-radius: 6px;
}

.brand-wordmark {
  display: block;
  width: 11rem;
  max-width: 100%;
}

.brand-wordmark__image {
  display: block;
  width: 100%;
  height: auto;
}

.site-navigation {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
}

.site-navigation a {
  position: relative;
  padding: 0.75rem 0.625rem;
  border-radius: 6px;
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
  text-align: center;
  text-decoration: none;
}

.site-navigation a:hover {
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}

.site-navigation a.active {
  background: var(--colour-primary-soft);
  color: var(--colour-text);
}

.site-navigation a.active::after {
  content: '';
  position: absolute;
  right: 0.625rem;
  bottom: 0.375rem;
  left: 0.625rem;
  border-bottom: 2px solid var(--colour-primary);
}

.brand-asset--night {
  display: none;
}

:root[data-theme='night'] .brand-asset--day {
  display: none;
}

:root[data-theme='night'] .brand-asset--night {
  display: block;
}

.theme-control {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--colour-text-secondary);
}

.theme-control__label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.theme-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.625rem;
  cursor: pointer;
}

.theme-toggle input {
  position: absolute;
  width: 2.75rem;
  height: 1.5rem;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.theme-toggle__track {
  width: 2.75rem;
  height: 1.5rem;
  flex: 0 0 auto;
  padding: 0.1875rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
}

.theme-toggle__thumb {
  display: block;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: var(--colour-primary);
  transform: translateX(0);
  transition: transform 160ms ease;
}

.theme-toggle input:checked + .theme-toggle__track .theme-toggle__thumb {
  transform: translateX(1.25rem);
}

.theme-toggle input:focus-visible + .theme-toggle__track {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.theme-control__value {
  min-width: 5.75rem;
  color: var(--colour-text);
  font-size: 0.875rem;
  font-weight: 600;
}

main {
  flex: 1;
}

.auth-page {
  min-height: min(42rem, calc(100svh - 13.5rem));
  display: grid;
  place-items: center;
  padding-block: 4rem;
}

.auth-card {
  width: min(100%, 47.5rem);
  padding: 3rem;
  border: 1px solid var(--colour-border);
  border-radius: 10px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.auth-card h1 {
  font-size: clamp(2.5rem, 8vw, 3.5rem);
  white-space: normal;
}

.auth-card__introduction,
.auth-card > p:not(.eyebrow, .auth-error) {
  max-width: 38rem;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.auth-card__introduction {
  margin: 1.25rem 0 2rem;
  font-size: 1.0625rem;
}

.button {
  min-height: 3rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.25rem;
  border: 1px solid transparent;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
}

.button--primary {
  background: var(--colour-primary);
  color: #fff;
}

:root[data-theme='night'] .button--primary {
  color: #08121b;
}

.button:disabled {
  cursor: wait;
  opacity: 0.72;
}

.auth-error {
  margin: 1rem 0 0;
  color: var(--colour-error);
  font-weight: 600;
}

.auth-card__alternative {
  margin: 2rem 0 0;
}

.identity-details {
  margin: 2rem 0 0;
}

.identity-details div {
  padding-block: 1rem;
  border-block: 1px solid var(--colour-border);
}

.identity-details dt {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.identity-details dd {
  margin: 0.5rem 0 0;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.submission-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.submission-page__heading {
  border-bottom: 2px solid var(--colour-primary);
}

.submission-form {
  display: grid;
  gap: 2rem;
  max-width: 62rem;
  padding-top: 2rem;
}

.submission-field {
  display: grid;
  gap: 0.625rem;
}

.submission-field label {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

.submission-field select,
.submission-field textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.submission-field select {
  min-height: 3rem;
  padding: 0.625rem 0.75rem;
}

.submission-field textarea {
  min-height: 24rem;
  padding: 1rem;
  resize: vertical;
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.875rem;
  line-height: 1.55;
  tab-size: 2;
  white-space: pre;
  overflow: auto;
}

.submission-field textarea[aria-invalid='true'] {
  border-color: var(--colour-error);
  box-shadow: 0 0 0 1px var(--colour-error);
}

.field-help,
.submission-progress {
  margin: 0;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.field-help code {
  padding: 0.1rem 0.3rem;
  border-radius: 3px;
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}

.submission-form > .button {
  justify-self: start;
}

.submission-result {
  padding: 1.5rem;
  border-left: 4px solid var(--colour-primary);
  background: var(--colour-primary-soft);
}

.submission-result--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.submission-result h2 {
  max-width: none;
  font-size: 1.5rem;
}

.submission-result h2:focus {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.submission-result > p {
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.55;
}

.submission-reference {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin: 1.5rem 0 0;
}

.submission-reference div {
  min-width: 0;
}

.submission-reference dt {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.submission-reference dd {
  margin: 0.375rem 0 0;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.validation-results {
  display: grid;
  gap: 0.75rem;
  margin: 1.5rem 0 0;
  padding-left: 1.5rem;
}

.validation-results li {
  padding-left: 0.25rem;
}

.validation-results strong,
.validation-results span {
  display: block;
}

.validation-results span {
  margin-top: 0.25rem;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.hero {
  position: relative;
  min-height: min(39rem, calc(100svh - 7.5rem));
  overflow: hidden;
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-canvas);
}

.hero::before,
.hero::after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.hero::before {
  inset: 2rem 0 2rem 50%;
  border-left: 1px solid var(--colour-border);
}

.hero::after {
  right: 3rem;
  bottom: 2rem;
  width: 7rem;
  border-bottom: 0.5rem solid var(--colour-brand);
}

.hero__content {
  position: relative;
  z-index: 2;
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
  padding-block: 4rem;
}

.eyebrow {
  margin: 0 0 1rem;
  color: var(--colour-label);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  overflow-wrap: anywhere;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  letter-spacing: 0;
}

h1 {
  margin: 0;
  font-size: 4.5rem;
  line-height: 1;
  text-wrap: balance;
  white-space: nowrap;
}

.hero__tagline {
  max-width: 30rem;
  margin: 1.5rem 0 0;
  color: var(--colour-brand);
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.15;
}

.hero__summary {
  max-width: 35rem;
  margin: 1.5rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.125rem;
  line-height: 1.6;
}

.hero__brand-art {
  position: absolute;
  z-index: 1;
  right: max(1.5rem, calc((100vw - 100rem) / 2));
  bottom: -1rem;
  width: min(38vw, 31rem);
  pointer-events: none;
}

.hero__logo {
  width: 100%;
  height: auto;
}

.principles {
  padding-block: 5rem;
  background: var(--colour-surface);
}

.section-heading {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 2fr);
  align-items: end;
  gap: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--colour-border);
}

.section-heading .eyebrow {
  margin: 0;
}

h2 {
  max-width: 18ch;
  margin: 0;
  font-size: 2.5rem;
  line-height: 1.1;
}

.principles__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2.5rem;
}

.principles article {
  padding-top: 2rem;
}

.principle-number {
  margin: 0 0 2rem;
  color: var(--colour-brand-text);
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 700;
}

h3 {
  margin: 0;
  font-size: 1.5rem;
  line-height: 1.2;
}

.principles article p:last-child {
  max-width: 28ch;
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.site-footer {
  border-top: 1px solid var(--colour-border);
  background: var(--colour-surface-raised);
}

.site-footer__inner {
  min-height: 8rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-footer p {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.browse-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.page-heading {
  padding-block: 3.5rem 2.5rem;
}

.page-heading h1 {
  max-width: 20ch;
  margin: 0;
  font-size: 3.25rem;
  line-height: 1;
  white-space: normal;
}

.page-heading > p:last-child {
  max-width: 47rem;
  margin: 1rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.0625rem;
  line-height: 1.6;
}

.browse-page__content {
  display: grid;
  gap: 3rem;
}

.filter-panel {
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
}

.filter-panel__heading,
.results-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.filter-panel h2,
.results-heading h2,
.related-records h2 {
  max-width: none;
  font-size: 1.5rem;
}

.text-link,
.back-link {
  color: var(--colour-link);
  font-weight: 650;
  text-underline-offset: 0.2em;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-block: 1.25rem;
}

.field {
  display: grid;
  align-content: start;
  gap: 0.5rem;
  min-width: 0;
}

.field span {
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
}

.field input,
.field select {
  width: 100%;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.button {
  display: inline-flex;
  min-height: 2.75rem;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1rem;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 700;
  text-decoration: none;
}

.button--primary {
  background: var(--colour-primary);
  color: var(--colour-surface);
}

:root[data-theme='night'] .button--primary {
  color: var(--colour-canvas);
}

.button--secondary {
  border-color: var(--colour-border);
  background: var(--colour-surface);
  color: var(--colour-text);
}

.button:hover {
  filter: brightness(0.94);
}

.results-region {
  min-width: 0;
}

.results-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.results-heading p {
  margin: 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
}

.record-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.record-list__item {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 1.8fr) minmax(12rem, 1fr);
  align-items: center;
  gap: 1.5rem;
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-list__meta,
.record-list__summary {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  line-height: 1.5;
}

.record-list__item h3 {
  min-width: 0;
}

.record-list__item h3 a {
  color: var(--colour-text);
  text-decoration-color: var(--colour-primary);
  text-decoration-thickness: 2px;
  text-underline-offset: 0.2em;
}

.state-message {
  margin-top: 1.5rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.state-message--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.state-message h1,
.state-message h3,
.state-message p {
  max-width: 48rem;
}

.state-message h1,
.state-message h3 {
  margin: 0;
  white-space: normal;
}

.state-message p {
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.state-message .button {
  margin-top: 1rem;
}

.pagination {
  display: flex;
  justify-content: flex-end;
  padding-top: 1.5rem;
}

.pagination__end {
  margin: 1.5rem 0 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
  text-align: right;
}

.detail-page {
  min-height: 38rem;
  padding-block: 2.5rem 5rem;
}

.page-heading--detail {
  padding-block: 2.5rem 2rem;
  border-bottom: 2px solid var(--colour-primary);
}

.record-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 2rem;
  margin: 0;
}

.record-facts > div {
  min-width: 0;
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-facts dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.record-facts dd {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 700;
}

.related-records {
  margin-top: 3rem;
}

.related-records > div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
  margin-top: 1rem;
}

.related-records a {
  font-weight: 700;
  text-underline-offset: 0.2em;
}

.state-message--detail {
  margin-top: 2rem;
}

