  label,
  requestKey,
  load,
  render,
}: {
  label: string;
  requestKey: string;
  load(signal: AbortSignal): Promise<Value>;
  render(value: Value): ReactNode;
}) {
  const state = usePublicData(load, requestKey);

  if (state.status === 'loading') {
    return (
      <div className="detail-page content-boundary">
        <DetailLoading label={label} />
