import { chromium, devices } from '@playwright/test';

const baseUrl = process.argv[2];

const inningsStatistic = {
  statisticId: 'stat-innings-1',
  fixtureId: 'fixture-1',
  scope: 'innings',
  statisticCode: 'team_total',
  inningsId: 'innings-1',
  inningsOrdinal: 0,
  competitorId: 'team-1',
  sourceEventCount: 120,
  metrics: { deliveryRuns: 154, penaltyRuns: 5, totalRuns: 159 },
};

const participantStatistic = {
  statisticId: 'stat-participant-1',
  fixtureId: 'fixture-1',
  scope: 'participant',
  statisticCode: 'participant_fixture',
  participantId: 'player-1',
  competitorId: 'team-1',
  sourceEventCount: 38,
  batting: { runsScored: 42, ballsFaced: 30, strikeRate: 140, fours: 4, sixes: 2 },
  bowling: {
    runsConceded: 24,
    legalBallsBowled: 18,
    oversBowled: '3.0',
    economyRate: 8,
    wicketsTaken: 2,
  },
};

const responseBody = {
  data: {
    fixtureId: 'fixture-1',
    status: 'complete',
    scope: { superOversIncluded: false },
    outcome: {
      kind: 'won',
      winnerCompetitorId: 'team-1',
      eliminatorCompetitorId: null,
      margin: { type: 'wickets', value: 5 },
      method: null,
      decidedByBowlOut: false,
    },
    warnings: [],
    statistics: [inningsStatistic, participantStatistic],
  },
};

const browser = await chromium.launch();

for (const target of [
  {
    context: { viewport: { width: 1440, height: 900 }, colorScheme: 'light' },
    path: 'evidence/validation/issue-54-public-statistics-desktop.png',
  },
  {
    context: { ...devices['Pixel 7'], colorScheme: 'light' },
    path: 'evidence/validation/issue-54-public-statistics-mobile.png',
  },
]) {
  const context = await browser.newContext(target.context);
  const page = await context.newPage();
  page.on('request', (request) => {
    if (request.resourceType() === 'fetch') console.log(`FETCH ${request.url()}`);
  });
  await page.route('**/*', (route) => {
    if (new URL(route.request().url()).pathname.endsWith('/fixtures/fixture-1/statistics')) {
      return route.fulfill({ json: responseBody });
    }

    return route.continue();
  });
  await page.goto(`${baseUrl}/fixtures/fixture-1/statistics`);
  await page.waitForTimeout(1000);
  console.log(await page.locator('main').innerText());
  await page.getByRole('heading', { level: 1, name: 'Fixture statistics', exact: true }).waitFor();
  await page.screenshot({ path: target.path, fullPage: true });
  await context.close();
}

await browser.close();

